#!/usr/bin/env python3
# luxarch:unpushed-stop-guard hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Refuse to end the turn with commits sitting unpushed — unless a hold is RECORDED.

FLEET-AGENT-CONDUCT-STANDARD: "Nothing is done until its gate is green AND the work is pushed.
A local-only pile is invisible and not done." A repo carrying a dozen unpushed commits is the
exact failure this catches, and it is invisible to every file-based guard.

But the hold is often CORRECT. Pushing is outward-facing; an agent told to wait for
authorization should NOT push, and blocking it forever turns the conduct standard against
itself — one wasted turn per attempt, indefinitely (one agent hit exactly that across four
consecutive turns). The sibling `luxpm-stop-guard` blocks on state the agent controls, so its
override is honest; this one blocks on an action requiring someone ELSE's consent, so it must
accept a recorded reason rather than demand compliance.

The first version's message named an escape — "or say explicitly why it is being held back" —
that the code never implemented. So the escape is now a FACT the hook can read: write the
reason to `.claude/.push-hold`. It is recorded in the tree, surfaced every turn so it cannot
rot into a silent exemption, and cleared with `rm` + push.

Stop hook: block while HEAD is ahead of upstream with commits THIS session made, and no hold is
recorded. No upstream / detached HEAD passes. Self-contained on purpose — a hook must not depend on
import-path manipulation to run.

Whose commits: v2 judged the repository, "HEAD is ahead of upstream". With two agents in one tree, a
session that had committed nothing was blocked at every stop by the other agent's commits, which it
must not push, and the only way out it offered (a `.push-hold`) recorded a hold that was not its
own. `luxpm-record-commit` (v3) records each commit with the session that made it in
`.claude/.session-commits.json`; this guard blocks only on this session's unpushed commits (matched
by sha, or by subject after an amend or rebase) and names the others in one line. A commit whose
change is already upstream counts as pushed (`git cherry`), which is what pushing your own commits
from a scratch worktree leaves behind (`--doc FLEET-AGENT-CONDUCT-STANDARD`, "Two agents in one
tree"). Where that
recorder is not installed, or the hook payload carries no session, it judges the repository as
before rather than let a session off.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path

HOLD = ".claude/.push-hold"
COMMITS = ".claude/.session-commits.json"
RECORDER = ".claude/hooks/luxpm-record-commit.py"
_EVENT: dict[str, object] = {}


def project_dir() -> Path:
    d = os.environ.get("CLAUDE_PROJECT_DIR")
    if d:
        return Path(d)
    try:
        return Path(
            subprocess.check_output(
                ["git", "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        )
    except Exception:
        return Path.cwd()


def git(*args: str) -> str:
    try:
        return subprocess.check_output(
            ["git", "-C", str(project_dir()), *args],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        return ""


def _event() -> dict[str, object]:
    """The hook payload, read from stdin once."""
    global _EVENT
    if not _EVENT:
        try:
            _EVENT = json.load(sys.stdin) or {}
        except Exception:
            _EVENT = {"_unread": True}
    return _EVENT


def _already_blocked() -> bool:
    """True when this Stop hook has ALREADY blocked once this turn.

    Claude Code sets `stop_hook_active` on the re-entry after a Stop hook blocks. Honouring it is
    what makes a Stop guard a reminder rather than a trap: it gets one turn to put the obligation
    in front of the agent, then stands down. Without it the hook loops until the harness
    force-overrides — nine consecutive turns, observed live — and an agent that legitimately
    cannot comply (a push awaiting authorization) has no way out at all."""
    return bool(_event().get("stop_hook_active"))


def _recorder_installed() -> bool:
    try:
        text = (project_dir() / RECORDER).read_text(encoding="utf-8")
    except OSError:
        return False
    m = re.search(r"luxpm-record-commit hook v(\d+)", text)
    return m is not None and int(m.group(1)) >= 3


def _mine(ahead: list[tuple[str, str]]) -> list[tuple[str, str]] | None:
    """The unpushed commits this session made, or None when that cannot be known."""
    session = str(_event().get("session_id") or os.environ.get("CLAUDE_SESSION_ID", ""))
    if not session or not _recorder_installed():
        return None
    try:
        data = json.loads((project_dir() / COMMITS).read_text(encoding="utf-8"))
    except Exception:
        data = []
    entries = [e for e in data if isinstance(e, dict)] if isinstance(data, list) else []
    own = [e for e in entries if not e.get("session") or e.get("session") == session]
    shas = {str(e.get("sha")) for e in own}
    subjects = {str(e.get("subject")) for e in own}
    return [(sha, subj) for sha, subj in ahead if sha in shas or subj in subjects]


def main() -> int:
    if _already_blocked():
        return 0
    upstream = git("rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
    if not upstream:
        return 0  # no upstream configured — nothing to be ahead of
    log = git("log", "--format=%H%x00%s", f"{upstream}..HEAD")
    commits = [
        tuple(line.split("\x00", 1)) for line in log.splitlines() if "\x00" in line
    ]
    # `git cherry`: "+" is a commit whose change is not upstream yet; "-" has an equivalent there
    # (pushed by cherry-pick from a scratch worktree), so it is not owed a push.
    pending = {
        line[2:].strip()
        for line in git("cherry", upstream, "HEAD").splitlines()
        if line.startswith("+ ")
    }
    pairs = [(c[0], c[1]) for c in commits if len(c) == 2 and c[0] in pending]
    if not pairs:
        return 0
    mine = _mine(pairs)
    if mine is not None and not mine:
        # Another session's commits: not this one's to push, and not its hold to record.
        print(
            f"{len(pairs)} commit(s) ahead of {upstream} were made by another session; "
            "they are that session's to push.",
            file=sys.stderr,
        )
        return 0
    ahead = str(len(mine) if mine is not None else len(pairs))
    interleaved = mine is not None and len(mine) < len(pairs)

    try:
        reason = (project_dir() / HOLD).read_text(encoding="utf-8").strip()
    except OSError:
        reason = ""
    if reason:
        # A recorded hold is a DECISION, not a dodge — print it every turn so it stays visible
        # and cannot quietly become a permanent exemption.
        print(
            f"{ahead} commit(s) held back from {upstream} — recorded in {HOLD}:\n"
            f"  {reason}\n"
            f"Clear it (`rm {HOLD}`) and push once the hold no longer applies.",
            file=sys.stderr,
        )
        return 0

    print(
        f"{ahead} commit(s) are committed but NOT pushed to {upstream}.\n"
        "Local-only work is invisible and does not count as done — `git push` before finishing.\n"
        "If the hold is DELIBERATE (waiting on authorization for an outward-facing push, a "
        "release not yet approved), record it and this stands down:\n"
        f'  echo "why it is held" > {HOLD}'
        + (
            "\nOther sessions' commits are among yours: push only your own, cherry-picked onto "
            'upstream in a scratch worktree (--doc FLEET-AGENT-CONDUCT-STANDARD, "Two agents in '
            'one tree"). Their presence is not a reason to hold.'
            if interleaved
            else ""
        ),
        file=sys.stderr,
    )
    return 2


sys.exit(main())
